WITH exploded AS (SELECT id, host, log_ts, status_code, attr_key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS attr_key, v), parsed AS (SELECT status_code, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 1) != 0 AS INT) AS flag_bit1 FROM exploded), base AS (SELECT *, flag_bit1 * status_code_high AS flag_bit1_times_status_code_high FROM parsed WHERE status_code <= 317), metrics AS (SELECT *, DENSE_RANK() OVER (ORDER BY flag_bit1_times_status_code_high) AS flag_bit1_times_status_code_high_dense_rank, PERCENT_RANK() OVER (ORDER BY flag_bit1 DESC NULLS FIRST) AS flag_bit1_percent_rank FROM base), with_windows AS (SELECT status_code, status_code_high, flag_bit1_times_status_code_high, flag_bit1_times_status_code_high_dense_rank, flag_bit1_percent_rank, CUME_DIST() OVER (ORDER BY flag_bit1_times_status_code_high_dense_rank DESC NULLS FIRST) AS flag_bit1_times_status_code_high_dense_rank_cume_dist, RANK() OVER w_hist AS flag_bit1_times_status_code_high_rank FROM metrics WINDOW w_hist AS (ORDER BY flag_bit1_times_status_code_high DESC NULLS FIRST)), cleaned AS (SELECT flag_bit1_times_status_code_high, flag_bit1_times_status_code_high_dense_rank, flag_bit1_percent_rank, flag_bit1_times_status_code_high_dense_rank_cume_dist, flag_bit1_times_status_code_high_rank, flag_bit1_times_status_code_high_dense_rank - status_code_high AS flag_bit1_times_status_code_high_dense_rank_minus_status_code_high FROM with_windows WHERE flag_bit1_times_status_code_high_rank < 6) SELECT flag_bit1_times_status_code_high, flag_bit1_times_status_code_high_dense_rank, flag_bit1_percent_rank, flag_bit1_times_status_code_high_rank, flag_bit1_times_status_code_high_dense_rank_minus_status_code_high, CUME_DIST() OVER (ORDER BY flag_bit1_times_status_code_high NULLS FIRST) AS flag_bit1_times_status_code_high_cume_dist, CUME_DIST() OVER (ORDER BY flag_bit1_times_status_code_high_dense_rank DESC NULLS LAST) AS flag_bit1_times_status_code_high_dense_rank_cume_dist_2 FROM cleaned WHERE flag_bit1_times_status_code_high_dense_rank_minus_status_code_high IS NOT NULL
